{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C14"],
      "claim": "Ketoconazole, the closest azole antifungal analogue (Morgan 0.2791), has a mean oral bioavailability of approximately 75% in healthy volunteers, directly supporting that the imidazole-dichlorophenyl ether scaffold can achieve F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "A conflicting ketoconazole record reports low oral bioavailability at 100–400 mg every 12 hours, indicating absorption can be variable and context-dependent; this is a minority observation against multiple high-F ketoconazole measurements.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C02"],
      "claim": "Clotrimazole, a less similar azole antifungal, has low oral bioavailability; this is a cautionary low-F example, but its lower structural transferability to the query does not outweigh the supportive azole evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The most transferable evidence, ketoconazole, shows high human oral bioavailability (~75–90%), and the query shares the key imidazole-dichlorophenyl ether motif. The low-F azole example clotrimazole is less structurally similar and miconazole is not as poorly absorbed. Broader high-F records weakly corroborate that lipophilic azole-containing drugs can exceed the 20% threshold, so high is better supported.",
  "evidence_gaps": [
    "No direct experimental bioavailability record for the query molecule (miconazole) is present in the evidence set.",
    "Morgan similarities are low (<0.3), limiting quantitative transferability.",
    "Ketoconazole has conflicting bioavailability reports, and clotrimazole provides an opposing low-F example.",
    "Formulation, dose, and solubility conditions that strongly affect azole absorption are not fully matched."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

